<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import WorkspaceLogin from '@/components/common/WorkspaceLogin.vue'
import { workspaceApi as api,workspaceToken,workspaceLogout,workspaceRequiresLogin,workspaceAccessReady,loadWorkspaceAccess,type KnowledgeBase,type ModelConnection,type CampusAgent,type AgentRelease,type AgentAnswer,type WorkspaceRun } from '@/services/workspace'
import { useAppStore } from '@/stores/app'
import '@/assets/workspace.css'
const router=useRouter(),store=useAppStore(),bases=ref<KnowledgeBase[]>([]),models=ref<ModelConnection[]>([]),agents=ref<CampusAgent[]>([]),releases=ref<AgentRelease[]>([]),runs=ref<WorkspaceRun[]>([])
const tab=ref('agent'),selectedId=ref<number|null>(null),busy=ref(false),error=ref(''),modelModal=ref(false),modelEditId=ref<number|undefined>()
const defaultPrompt='你是新生智游校园助手。当前日期：{{current_date}}，当前校区：{{campus}}，适用人群：{{audience}}。\n优先使用已审核标准问答；没有可靠直答时依据检索资料回答。\n校园事实必须有依据，资料不足时明确说明。\n路线必须通过后端导航工具计算，不得编造距离或执行成功。'
const form=reactive({name:'校园新生助手',baseId:null as number|null,modelId:null as number|null,systemPrompt:defaultPrompt})
const modelForm=reactive({name:'',kind:'CHAT',baseUrl:'',modelId:'',apiKeyEnv:''})
const query=ref(''),campus=ref(''),audience=ref(''),published=ref(false),answer=ref<AgentAnswer|null>(null),selectedRun=ref<WorkspaceRun|null>(null)
const variables=['{{current_date}}','{{campus}}','{{audience}}']
const loading=ref(true)
const modes:Record<string,string>={FAQ_DIRECT:'审核问答直答',RETRIEVAL_ONLY:'仅检索，未调用模型',LLM_RAG:'真实模型RAG',NO_EVIDENCE:'未找到依据',MODEL_ERROR:'模型调用失败',CLARIFY:'需要澄清',ROUTE_TOOL:'后端路线工具',STALE_EVIDENCE:'资料已变更'}
const current=computed(()=>agents.value.find(a=>a.id===selectedId.value))
const dirty=computed(()=>!current.value||JSON.stringify([form.name,form.baseId,form.modelId,form.systemPrompt])!==JSON.stringify([current.value.name,current.value.baseId,current.value.modelId??null,current.value.systemPrompt]))
async function act(task:()=>Promise<unknown>,success?:string){if(busy.value)return;busy.value=true;error.value='';try{await task();if(success)store.notify(success)}catch(e){error.value=e instanceof Error?e.message:'操作失败';store.notify(error.value,'warning')}finally{busy.value=false}}
function applyAgent(){const value=current.value;if(value){Object.assign(form,{name:value.name,baseId:value.baseId,modelId:value.modelId??null,systemPrompt:value.systemPrompt});const base=bases.value.find(b=>b.id===value.baseId);campus.value=base?.campus??'';audience.value=base?.audience??''}else{Object.assign(form,{name:'校园新生助手',baseId:bases.value[0]?.id??null,modelId:null,systemPrompt:defaultPrompt})}answer.value=null;releases.value=[];if(value)void api.releases(value.id).then(rs=>{if(selectedId.value===value.id)releases.value=rs}).catch(e=>{error.value=e.message})}
async function load(){loading.value=true;error.value='';try{await loadWorkspaceAccess();if(workspaceRequiresLogin.value&&!workspaceToken.value)return;const [bs,ms,as,rs]=await Promise.all([api.bases(),api.models(),api.agents(),api.runs()]);bases.value=bs;models.value=ms;agents.value=as;runs.value=rs;if(selectedId.value&&!as.some(a=>a.id===selectedId.value))selectedId.value=null;if(selectedId.value==null&&as.length)selectedId.value=as[0]!.id;else applyAgent()}catch(e){error.value=e instanceof Error?e.message:'读取失败'}finally{loading.value=false}}
function newAgent(){selectedId.value=null;applyAgent()}
async function saveAgent(){if(!form.baseId){error.value='请先选择或创建知识库';return}await act(async()=>{const value=await api.saveAgent({...form},selectedId.value??undefined);const index=agents.value.findIndex(a=>a.id===value.id);if(index>=0)agents.value[index]=value;else agents.value.push(value);selectedId.value=value.id;applyAgent()},'智能体草稿已保存')}
async function publish(){if(!selectedId.value||dirty.value)return;const note=window.prompt('填写本次发布说明（不填写密钥）','校园助手配置发布');if(note==null)return;await act(async()=>{await api.publish(selectedId.value!,note);await load()},'正式版本快照已保存；仍跟随最新已审核知识')}
async function rollback(release:AgentRelease){if(!selectedId.value||!window.confirm(`将正式版本恢复为 #${release.id}？草稿不会被覆盖。`))return;await act(async()=>{await api.rollback(selectedId.value!,release.id);await load()},'正式版本已回滚')}
async function debug(){if(!selectedId.value||!query.value.trim())return;answer.value=null;await act(async()=>{answer.value=await api.chat(selectedId.value!,query.value,published.value,campus.value,audience.value);runs.value=await api.runs()})}
function openModel(value?:ModelConnection){modelEditId.value=value?.id;Object.assign(modelForm,{name:'',kind:'CHAT',baseUrl:'',modelId:'',apiKeyEnv:''},value??{});modelModal.value=true}
async function saveModel(){await act(async()=>{await api.saveModel({...modelForm},modelEditId.value);models.value=await api.models();modelModal.value=false},'连接已保存，需点击真实连接测试')}
async function testModel(value:ModelConnection){if(!window.confirm('将向配置的模型服务发起一次真实请求，可能产生服务商费用。继续？'))return;await act(async()=>{const tested=await api.testModel(value.id);models.value=models.value.map(m=>m.id===tested.id?tested:m);store.notify(tested.testMessage||tested.testStatus,tested.testStatus==='SUCCESS'?'success':'warning')})}
async function refreshRuns(){await act(async()=>{runs.value=await api.runs()})}
watch(selectedId,applyAgent);watch(workspaceToken,value=>{if(value)void load();else{agents.value=[];models.value=[];runs.value=[];answer.value=null}});onMounted(load)
</script>

<template>
  <div v-if="!workspaceAccessReady" class="kw-page"><p v-if="error" class="kw-alert">{{ error }} <button class="kw-link" @click="load">重试</button></p><p v-else class="kw-empty">正在连接工作台…</p></div>
  <WorkspaceLogin v-else-if="workspaceRequiresLogin&&!workspaceToken" @authenticated="load" />
  <div v-else class="kw-page"><header class="kw-heading"><div><span class="kw-eyebrow">CAMPUS AGENT STUDIO</span><h2>校园智能体工作台</h2><p>提示词版本 · 审核知识 · 真实模型与工具 · 可追溯调试</p></div><div class="kw-actions"><button class="btn" @click="router.push('/knowledge')">管理知识库</button><button v-if="workspaceRequiresLogin" class="btn" @click="workspaceLogout">退出</button></div></header>
    <p v-if="!workspaceRequiresLogin" class="kw-note">开发演示模式 · 局域网免登录，仅在可信 WiFi 下使用；请勿暴露到公网。</p>
    <p v-if="error" class="kw-alert" role="alert">{{ error }}</p>
    <div v-if="loading" class="kw-empty">正在读取智能体配置…</div><template v-else>
    <nav class="kw-tabs"><button :class="{active:tab==='agent'}" @click="tab='agent'">配置与调试</button><button :class="{active:tab==='models'}" @click="tab='models'">模型连接</button><button :class="{active:tab==='releases'}" @click="tab='releases'">发布与回滚</button><button :class="{active:tab==='runs'}" @click="tab='runs';refreshRuns">调试运行记录</button></nav>
    <div v-if="tab==='agent'||tab==='releases'" class="kw-toolbar"><div class="kw-actions"><select v-model="selectedId" class="select-input"><option :value="null">新建智能体草稿</option><option v-for="a in agents" :key="a.id" :value="a.id">{{ a.name }}</option></select><span v-if="current?.publishedRevisionId" class="tag green">正式版本 #{{ current.publishedRevisionId }}</span><span v-else class="tag orange">尚未发布</span></div><button class="btn" @click="newAgent">＋ 新建智能体</button></div>
    <div v-if="tab==='agent'" class="kw-agents-layout"><section class="panel kw-card"><div class="kw-section-head"><h3>智能体配置</h3><span class="tag">{{ dirty?'草稿有未保存修改':'草稿已保存' }}</span></div><form class="kw-form-stack" @submit.prevent="saveAgent"><label>智能体名称<input v-model="form.name" maxlength="100" required></label><label>绑定知识库<select v-model="form.baseId" required><option :value="null">请选择知识库</option><option v-for="base in bases" :key="base.id" :value="base.id">{{ base.name }}</option></select></label><label>对话模型<select v-model="form.modelId"><option :value="null">未配置（仅精确直答 / 全文检索 / 路线工具）</option><option v-for="model in models.filter(m=>m.kind==='CHAT')" :key="model.id" :value="model.id">{{ model.name }} · {{ model.testStatus==='SUCCESS'?'已测试':'未通过测试' }}</option></select></label><div class="kw-section-head"><b>系统提示词</b><span class="kw-muted">变量由后端安全替换</span></div><div class="kw-chips"><button v-for="variable in variables" :key="variable" type="button" class="kw-link" @click="form.systemPrompt+=' '+variable">{{ variable }}</button></div><textarea v-model="form.systemPrompt" rows="13" maxlength="16000" required/><p class="kw-note">参考资料会放入单独的用户上下文，不作为系统指令。当前为单轮调试；多轮记忆、模型工具自主循环与流式输出尚未开放。</p><div class="kw-actions"><button class="btn primary" :disabled="busy">保存草稿</button><button type="button" class="btn" :disabled="busy||!selectedId||dirty" @click="publish">发布当前配置</button><button type="button" class="kw-link" @click="tab='models'">配置模型连接 ↗</button></div></form></section>
      <section class="panel kw-card"><div class="kw-section-head"><h3>对话调试</h3><span class="tag">仅调试流量</span></div><div class="kw-actions kw-wrap"><label><input v-model="published" type="checkbox" :disabled="!current?.publishedRevisionId"> 使用正式版本快照</label><span class="kw-muted">{{ published?'不使用当前未发布修改':'使用已保存草稿' }}</span></div><div class="kw-form-stack"><label>校区<input v-model="campus" placeholder="与知识库适用范围一致"></label><label>适用人群<input v-model="audience" placeholder="如：2026级本科新生"></label></div><textarea v-model="query" class="kw-textarea" rows="4" placeholder="输入实际问题，例如：饭卡在哪领？或从东门去图书馆"/><button class="btn primary kw-full" :disabled="busy||!selectedId||(!published&&dirty)||!query.trim()" @click="debug">{{ busy?'正在处理…':'运行测试' }}</button><p v-if="dirty&&!published" class="kw-muted">请先保存草稿再调试，避免页面配置与后端实际执行不一致。</p><template v-if="answer"><div class="kw-metrics"><span>{{ modes[answer.mode]||answer.mode }}</span><span>{{ answer.elapsedMs }} ms</span><span>运行 #{{ answer.runId }}</span><span v-if="answer.inputTokens!=null">输入 {{ answer.inputTokens }} / 输出 {{ answer.outputTokens??'未返回' }} Token</span></div><div class="kw-debug-answer">{{ answer.answer }}</div><p v-if="answer.route" class="kw-note">{{ answer.route.origin }} → {{ answer.route.destination }} · {{ answer.route.distanceMeters }}米 · 预计{{ answer.route.estimatedMinutes }}分钟</p><h4>实际检索证据</h4><div v-for="item in answer.evidence" :key="item.id" class="kw-evidence"><b>{{ item.title }}</b><small>{{ item.id }} · {{ item.page?'第'+item.page+'页 · ':'' }}{{ item.source||'来源待补充' }}</small><p>{{ item.content }}</p></div></template><div v-else class="kw-empty">调试结果、真实检索证据和模型用量将显示在这里。</div></section>
    </div>
    <section v-if="tab==='models'" class="panel kw-card"><div class="kw-section-head"><div><h3>模型连接</h3><p>采用兼容接口：CHAT /chat/completions，Embedding /embeddings，Rerank /rerank。密钥填写后端环境变量名。</p></div><button class="btn primary" @click="openModel()">＋ 添加模型连接</button></div><p class="kw-note">连接测试是显式真实请求，可能计费。Embedding/Rerank连接测试不等于已启用向量索引或重排；当前检索仍为中文全文BM25。</p><div class="kw-table-scroll"><table class="data-table"><thead><tr><th>连接</th><th>能力 / 模型ID</th><th>密钥</th><th>验证状态</th><th>操作</th></tr></thead><tbody><tr v-for="model in models" :key="model.id"><td><b>{{ model.name }}</b><small class="kw-block">{{ model.baseUrl }}</small></td><td>{{ model.kind }}<small class="kw-block">{{ model.modelId }}</small></td><td>{{ model.apiKeyEnv||'无认证配置' }}<small class="kw-block">{{ model.keyConfigured?'环境可用 / 无需密钥':'环境变量未设置' }}</small></td><td><span :class="['tag',model.testStatus==='SUCCESS'?'green':'orange']">{{ model.testStatus==='SUCCESS'?'真实测试成功':model.testStatus==='FAILED'?'测试失败':'尚未测试' }}</span><small class="kw-block">{{ model.testMessage }}</small></td><td><button class="kw-link" @click="openModel(model)">编辑</button><button class="kw-link" :disabled="busy" @click="testModel(model)">真实连接测试</button></td></tr><tr v-if="!models.length"><td colspan="5" class="kw-empty">尚未添加模型，问答直答和全文检索仍可独立使用。</td></tr></tbody></table></div></section>
    <section v-if="tab==='releases'" class="panel kw-card"><h3>发布记录</h3><p class="kw-muted">配置和模型参数保存快照；知识跟随最新审核版本，停用和有效期始终生效。回滚不覆盖当前草稿。</p><div v-for="release in releases" :key="release.id" class="kw-release"><div><b>版本 #{{ release.id }} {{ current?.publishedRevisionId===release.id?'· 当前正式版':'' }}</b><p>{{ release.releaseNote||'未填写说明' }} · {{ release.createdAt?.replace('T',' ').slice(0,16) }} · {{ release.providerModelId||'无生成模型' }}</p><details><summary>查看提示词快照</summary><pre class="kw-prompt-snapshot">{{ release.systemPrompt }}</pre></details></div><button class="btn" :disabled="busy||current?.publishedRevisionId===release.id" @click="rollback(release)">恢复此版本</button></div><p v-if="!releases.length" class="kw-empty">保存草稿后发布，即可生成可回滚的配置版本。</p></section>
    <section v-if="tab==='runs'" class="panel kw-card"><div class="kw-section-head"><div><h3>最近50次调试运行</h3><p>展示真实结果与耗时，不混入学生端咨询统计。未实现生成费用估算或质量百分比。</p></div><button class="btn" :disabled="busy" @click="refreshRuns">刷新</button></div><div class="kw-table-scroll"><table class="data-table"><thead><tr><th>时间</th><th>问题</th><th>方式</th><th>结果</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td>{{ run.createdAt?.replace('T',' ').slice(0,19) }}</td><td>{{ run.question }}</td><td>{{ modes[run.mode]||run.mode }}</td><td>{{ run.status }}</td><td>{{ run.elapsedMs }}ms</td><td><button class="kw-link" @click="selectedRun=run">查看</button></td></tr><tr v-if="!runs.length"><td colspan="6" class="kw-empty">暂无运行记录。</td></tr></tbody></table></div><div v-if="selectedRun" class="kw-debug-answer"><b>{{ selectedRun.question }}</b><p>{{ selectedRun.answer }}</p><small>证据ID：{{ selectedRun.sourceIds||'无' }} · 输入Token：{{ selectedRun.inputTokens??'服务商未返回' }} · 输出Token：{{ selectedRun.outputTokens??'服务商未返回' }}</small></div></section>
    <div v-if="modelModal" class="modal-backdrop" @click.self="!busy&&(modelModal=false)"><form class="modal kw-modal" @submit.prevent="saveModel"><div class="modal-head"><h3>模型连接</h3><button type="button" class="modal-close" @click="modelModal=false">×</button></div><p v-if="error" class="kw-alert">{{ error }}</p><div class="modal-body form-grid"><label class="form-field">连接名称<input v-model="modelForm.name" required></label><label class="form-field">能力<select v-model="modelForm.kind"><option value="CHAT">对话生成</option><option value="EMBEDDING">Embedding向量化</option><option value="RERANK">Rerank重排</option></select></label><label class="form-field full">服务基础地址<input v-model="modelForm.baseUrl" required placeholder="例如：https://服务商域名/v1（不要填完整chat/completions路径）"></label><label class="form-field full">模型ID<input v-model="modelForm.modelId" required placeholder="填写服务商实际提供的模型ID"></label><label class="form-field full">密钥环境变量名<input v-model="modelForm.apiKeyEnv" placeholder="如 CAMPUS_LLM_API_KEY；本地无认证服务可留空"></label><p class="kw-note form-field full">真实密钥只在后端启动环境设置。不要在此处粘贴密钥。修改连接后会重置验证状态。</p></div><div class="modal-foot"><button class="btn primary" :disabled="busy">保存连接配置</button></div></form></div>
  </template></div>
</template>
<style scoped>.kw-prompt-snapshot{white-space:pre-wrap;line-height:1.8;max-width:700px;color:#7d91ab;font-family:inherit}.kw-release details{font-size:11px}.kw-agents-layout h4{color:#5278a3;font-size:13px}</style>
